import {stages,roomList,tools} from './adventure.js';
import {fresh,restore,act,visible} from './play-engine.js';
const $=id=>document.getElementById(id),KEY='danchu-adventure-v5',reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
let raw=null;try{raw=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}
let state=restore(raw),selected=[],busy=false,actor={x:42,y:85,pose:0},camera=50,overview=false,geometry={w:0,h:0,scale:1,tx:0,ty:0},hint=0,sound=false,audio=null,codeTarget=null,code='',gesture=null,actorGesture=null,token=0;
const level=()=>stages[state.stage];
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function art(id,extra=''){const t=tools[id];if(id==='seal')return '<div class="star-piece" aria-hidden="true">✦</div>';return tile(t[1],t[2]==='old',extra,id==='oiled');}
function tile(index,old=false,extra='',oil=false){return `<div class="item-art ${old?'old':''} ${extra}" style="background-position:${index%4/3*100}% ${Math.floor(index/4)/3*100}%" aria-hidden="true">${oil?'<span class="oil-badge">●</span>':''}</div>`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:5,history:state.history}));}catch{say('기기 저장 공간이 부족해. 이 창에서는 계속 플레이할 수 있어.');}}
function say(t){$('message').textContent=t;}
function pose(p){actor.pose=p;$('actor-sprite').style.backgroundPosition=`${p%4/3*100}% ${Math.floor(p/4)*100}%`;}
function displayY(y){const h=geometry.h||window.innerHeight;return (160+(y-20)/60*Math.max(110,h-430))/h*100;}
function logicalY(y){const h=geometry.h;return 20+(y/100*h-160)/Math.max(110,h-430)*60;}
function actorPosition(){const el=$('actor');el.style.left=actor.x+'%';el.style.top=displayY(actor.y)+'%';pose(actor.pose);}
function layout(){const r=$('viewport').getBoundingClientRect();geometry.w=r.height*1.5;geometry.h=r.height;geometry.scale=overview?Math.min(1,r.width/geometry.w):1;const scaled=geometry.w*geometry.scale;geometry.tx=scaled<=r.width?(r.width-scaled)/2:Math.max(r.width-scaled,Math.min(0,r.width/2-camera/100*scaled));geometry.ty=(r.height-geometry.h*geometry.scale)/2;const w=$('world');w.style.width=geometry.w+'px';w.style.height=geometry.h+'px';w.style.transform=`translate(${geometry.tx}px,${geometry.ty}px) scale(${geometry.scale})`;$('pan-left').disabled=scaled<=r.width||geometry.tx>=0;$('pan-right').disabled=scaled<=r.width||geometry.tx<=r.width-scaled;$('zoom').textContent=overview?'크게 보기':'전체 보기';$('camera-label').textContent=scaled>r.width?'배경을 좌우로 밀어 둘러보세요':'물건을 눌러 가까이 보기';}
function focusAt(x){camera=Math.max(0,Math.min(100,x));layout();}
function worldPoint(e){const r=$('viewport').getBoundingClientRect();return{x:(e.clientX-r.left-geometry.tx)/(geometry.w*geometry.scale)*100,y:logicalY((e.clientY-r.top-geometry.ty)/(geometry.h*geometry.scale)*100)};}
function deviceFor(o){
 if(o.art!==undefined)return null;
 if(o.id==='drawer'||o.id==='case'||o.id==='folder')return state.flags.unlocked||state.flags.opened?1:0;
 if(o.id==='door'||o.id==='exit'||o.id==='hatch'||o.id==='inside')return state.flags.held||state.flags.turned||state.flags.raised?3:2;
 if(o.pad)return 4;
 if(o.id==='drain'||o.id==='gap')return 5;
 if(o.id==='machine'||o.id==='axle'||o.id==='contact'||o.id==='cover')return level().room>=4?11:6;
 if(o.id==='switch'||o.id==='play'||o.id==='hinge')return 7;
 if(o.id==='sensor'||o.id==='beam'||o.id==='glass')return 8;
 if(o.id==='stand'&&state.flags.reflected)return 9;
 if(o.id==='holder'&&state.flags.focused||o.id==='ring'&&state.flags.focused)return 10;
 if(o.id==='player'||o.id==='listen'||o.id==='horn')return 11;
 if(o.id==='mailbox')return state.flags.wound?13:12;
 if(o.id==='reader'||o.id==='slot'||o.id==='wrong')return 14;
 if(o.id==='left'||o.id==='right'||o.id==='lift')return 15;
 return null;
}
function deviceTile(index){return `<div class="item-art device-art" style="background-position:${index%4/3*100}% ${Math.floor(index/4)/3*100}%" aria-hidden="true"></div>`;}
// Keep props in room scale; the button remains at least 48px for touch.
function objectSize(o,device){
 const depth=.82+Math.max(0,Math.min(1,(o.y-25)/55))*.2;
 const base=o.art!==undefined?(o.width?98:o.tool==='key'?38:o.tool==='letter'||o.tool==='score'?48:52):device!==null?72:42;
 return Math.round(base*depth);
}
function renderObjects(){const l=level();$('objects').innerHTML=l.objects.filter(o=>visible(state,o)).map(o=>{const device=deviceFor(o),opened=o.openFlag&&state.flags[o.openFlag],used=l.rules.some(r=>r.target===o.id&&r.set&&state.flags[r.set]);return `<button class="object ${used?'done-object':''}" data-object="${o.id}" style="left:${o.x}%;top:${displayY(o.y)}%;--prop-size:${objectSize(o,device)}px;width:${Math.max(48,objectSize(o,device))}px" aria-label="${esc(o.name)}${opened?' · 열림':''}" ${o.tool?'draggable="false"':''}>${o.art!==undefined?(o.tool?art(o.tool):tile(opened?o.openArt:o.art)):device!==null?deviceTile(device): `<span class="target-mark">${o.symbol||'◇'}</span>`}<span class="object-label">${esc(o.name)}${opened?' · 열림':''}</span>${o.tool?'<i class="ready-dot"></i>':''}</button>`;}).join('');}
function renderBag(){$('world').classList.toggle('using-item',selected.length===1);$('bag').innerHTML=state.inventory.map(id=>`<button class="bag-item ${selected.includes(id)?'selected':''}" data-item="${id}" aria-pressed="${selected.includes(id)}" aria-label="${tools[id][0]} 선택">${art(id)}<span>${tools[id][0]}</span></button>`).join('')||'<span class="empty-bag">장면에서 얻은 물건이 여기에 모여요</span>';$('combine').hidden=selected.length!==2;$('dismiss-selection').hidden=!selected.length;$('instruction').textContent=selected.length===1?'선택한 물건을 장면에 누르거나 끌어 놓아 사용':selected.length===2?'조합 버튼을 누르거나 다른 소지품을 선택':'배경을 밀어 둘러보기 · 단추를 끌어 이동';}
function render(){const l=level(),room=roomList[l.room];$('chapter').textContent=room[1]+' · 별빛 온실';$('stage-number').textContent=String(l.id).padStart(2,'0');$('goal').textContent=l.goal;$('subgoal').textContent=`${l.id} / 30 · ${l.title}`;$('progress').style.width=state.completed.length/30*100+'%';$('room-image').src=`case-art/${room[0]}.webp`;$('room-image').alt=`${room[1]}. 따뜻한 조명과 목재 가구가 있는 손으로 그린 공간.`;$('light-beam').hidden=!l.rules.some(r=>r.beam&&state.flags[r.set]);layout();renderObjects();renderBag();actorPosition();save();}
function ping(notes=[660],force=false){if(!sound&&!force)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.33;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.09,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+.28);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.3);});}catch{}}
function sleep(ms){return new Promise(r=>setTimeout(r,reduced?0:ms));}
async function moveTo(o,finalPose=6){const dx=o.x-actor.x;pose(dx<0?2:3);$('actor').classList.add('walking');actor.x=Math.max(8,Math.min(92,o.x-7));actor.y=Math.max(64,Math.min(85,o.y+14));actorPosition();focusAt(o.x);await sleep(400);$('actor').classList.remove('walking');pose(finalPose);}
function fly(item,origin){if(reduced||!origin)return;const start=origin.getBoundingClientRect(),end=$('bag').getBoundingClientRect(),el=document.createElement('div');el.className='flying-item';el.innerHTML=art(item);el.style.left=start.left+start.width/2-40+'px';el.style.top=start.top+start.height/2-40+'px';document.body.append(el);requestAnimationFrame(()=>requestAnimationFrame(()=>{el.style.transform=`translate(${end.left+35-(start.left+start.width/2)}px,${end.top+25-(start.top+start.height/2)}px) scale(.45)`;el.style.opacity='.15';}));setTimeout(()=>el.remove(),850);}
async function perform(action){if(busy)return;const l=level(),o=l.objects.find(v=>v.id===action.target),r=act(state,action);say(r.message);if(!r.ok){pose(1);if(o)focusAt(o.x);return false;}busy=true;const serial=++token,origin=o?document.querySelector(`[data-object="${o.id}"]`):null;if(o)await moveTo(o,r.rule?.pose??6);if(serial!==token){busy=false;return false;}state=r.state;selected=selected.filter(i=>state.inventory.includes(i));if(action.type==='use'||action.type==='combine')selected=[];if(r.rule?.grant)fly(r.rule.grant,origin);render();if(r.rule?.reveal){$('world-reveal').textContent=r.rule.reveal;$('world-reveal').hidden=false;}if(r.rule?.set?.endsWith('_open'))document.querySelector(`[data-object="${o.id}"]`)?.classList.add('opening');if(r.rule?.beam)$('world').classList.add('scene-flash');if(r.rule?.melody)ping([261.63,329.63,293.66,392]);else ping([659,784]);say(r.message);if(state.flags.done){await sleep(550);showSuccess(r.message);}busy=false;return true;}
function showSuccess(message){const last=state.stage===29;$('success-title').textContent=last?'별빛 온실, 다시 열다':level().title+' · 해결!';$('success-copy').textContent=message;$('next').textContent=last?'완성한 모험 둘러보기':'다음 이야기 →';$('success').hidden=false;}
function select(id){selected=selected.includes(id)?selected.filter(x=>x!==id):[...selected.slice(-1),id];renderBag();say(selected.length===2?`${selected.map(i=>tools[i][0]).join(' + ')}. 두 물건을 조합해 볼까?`:selected.length===1?`${tools[id][0]} 선택. 사용할 곳을 장면에서 눌러줘.`:'선택을 해제했어.');}
function openCode(o){codeTarget=o;code='';const ready=(o.requires||[]).every(f=>state.flags[f]);$('detail-tag').textContent='단추가 직접 조작하기';$('detail-content').innerHTML=`<h2>${esc(o.name)}</h2><div class="detail-clue">${esc(ready?o.clue:'아직 읽을 수 있는 단서를 확인하지 못했어. 장면에서 방법을 찾아보자.')}</div>${ready?'<div class="code-readout" id="code-readout">— — —</div><div id="keypad">'+[1,2,3,4,5,6,7,8,9,'지우기',0,'확인'].map(k=>`<button data-key="${k}">${k}</button>`).join('')+'</div>':''}<p class="pad-feedback" id="pad-feedback"></p>`;$('detail').showModal();}
async function interact(id){if(busy)return;const o=level().objects.find(v=>v.id===id);if(!o||!visible(state,o))return;if(overview){overview=false;focusAt(o.x);}if(selected.length===1){await perform({type:'use',item:selected[0],target:id});return;}if(selected.length===2){say('조합 버튼을 눌러 두 도구를 합치거나 선택을 해제해 줘.');return;}if(o.pad){focusAt(o.x);openCode(o);return;}await perform({type:'tap',target:id});}
function enterStage(){token++;busy=false;selected=[];hint=0;overview=false;actor={x:42,y:85,pose:0};camera=level().objects[0]?.x??50;$('success').hidden=true;$('world-reveal').hidden=true;$('world').classList.remove('scene-flash');render();say(level().story);}
function replay(){const r=act(state,{type:'visit',stage:state.stage});if(r.ok){state=r.state;enterStage();}}
function map(){ $('stage-map').innerHTML=roomList.map((r,ri)=>`<section><h3>${r[1]} · ${r[2]}</h3><div class="stage-row">${stages.filter(l=>l.room===ri).map(l=>`<button data-stage="${l.id-1}" class="${state.stage===l.id-1?'current':state.completed.includes(l.id-1)?'completed':''}" ${l.id-1>Math.max(-1,...state.completed)+1?'disabled':''} aria-label="${l.id}단계 ${l.title}">${state.completed.includes(l.id-1)?'✓ ':''}${l.id}</button>`).join('')}</div></section>`).join('');$('map').showModal();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.close){$(b.dataset.close).close();return;}if(b.dataset.object){interact(b.dataset.object);return;}if(b.dataset.item){if(suppressItemClick){suppressItemClick=false;return;}select(b.dataset.item);return;}if(b.dataset.key){if(busy)return;const k=b.dataset.key;if(k==='지우기')code=code.slice(0,-1);else if(k==='확인'){const o=codeTarget,r=act(state,{type:'code',target:o.id,answer:code});if(r.ok){$('detail').close();await perform({type:'code',target:o.id,answer:code});}else{ $('pad-feedback').textContent=r.message;code='';}}else{code=(code+k).slice(0,codeTarget.answer.length);if(codeTarget.music)ping([{1:261.63,2:293.66,3:329.63,5:392}[k]||440]);}if($('code-readout'))$('code-readout').textContent=code.padEnd(codeTarget.answer.length,'—').split('').join(' ');return;}
 if(b.dataset.stage!==undefined){if(busy)return;const target=Number(b.dataset.stage);if(target>Math.max(-1,...state.completed)+1)return;$('map').close();if(target===state.stage)return;const r=act(state,{type:'visit',stage:target});if(r.ok)state=r.state;enterStage();return;}
 switch(b.id){case 'combine':perform({type:'combine',items:[...selected]});break;case 'dismiss-selection':selected=[];renderBag();say('선택을 해제했어. 다른 방법도 시도해 보자.');break;case 'next':if(state.stage===29){$('success').hidden=true;map();}else{const r=act(state,{type:'next'});if(r.ok){state=r.state;enterStage();}}break;case 'replay':replay();break;case 'menu':if(!busy)map();break;case 'zoom':overview=!overview;layout();break;case 'pan-left':overview=false;focusAt(camera-23);break;case 'pan-right':overview=false;focusAt(camera+23);break;case 'hint':hint=Math.min(hint+1,level().hints.length);say(`힌트 ${hint}/${level().hints.length} · ${level().hints[hint-1]}`);break;case 'sound':sound=!sound;$('sound').textContent=sound?'♪ ON':'♪ OFF';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'소리 끄기':'소리 켜기');if(sound)ping();break;case 'help':$('map').close();$('detail-tag').textContent='조작 방법';$('detail-content').innerHTML='<h2>정답을 누르기보다,<br>물건을 써 보세요.</h2><p>① 장면의 상자와 물건을 눌러요.<br>② 얻은 물건을 아래에서 고르고 장면에 사용해요.<br>③ 두 물건을 골라 조합할 수도 있어요.<br>④ 배경을 좌우로 밀면 방 전체를 둘러볼 수 있어요.</p><p>단추를 끌어 침대에 놓으면 이불을 덮고 쉬고, 창가에 놓으면 하늘을 봐요. 막히면 위쪽 ? 버튼을 눌러요.</p>';$('detail').showModal();break;case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen?.();else if($('game').requestFullscreen){try{await $('game').requestFullscreen();$('map').close();}catch{say('이 브라우저에서는 홈 화면에 추가하면 독립 화면으로 열 수 있어.');}}else{$('map').close();say('아이폰은 Safari 공유 → 홈 화면에 추가로 독립 화면에서 열 수 있어.');}break;case 'restart':$('map').close();$('detail-tag').textContent='처음부터 다시';$('detail-content').innerHTML='<h2>모험을 처음부터 시작할까요?</h2><p>이 기기에 저장된 현재 진행이 초기화돼요.</p><div class="detail-actions"><button data-close="detail">계속 플레이</button><button id="confirm-restart">처음부터 시작</button></div>';$('detail').showModal();break;case 'confirm-restart':state=fresh();$('detail').close();enterStage();break;}
});
const viewport=$('viewport');viewport.addEventListener('pointerdown',e=>{if(e.target.closest('.object,#actor')||busy||e.button!==0)return;gesture={id:e.pointerId,x:e.clientX,y:e.clientY,camera,moved:false};viewport.setPointerCapture(e.pointerId);});
viewport.addEventListener('pointermove',e=>{if(!gesture||e.pointerId!==gesture.id)return;const dx=e.clientX-gesture.x;if(Math.abs(dx)>6)gesture.moved=true;if(gesture.moved&&!overview){$('world').classList.add('dragging');camera=Math.max(0,Math.min(100,gesture.camera-dx/geometry.w*100));layout();}});
viewport.addEventListener('pointerup',async e=>{if(!gesture||e.pointerId!==gesture.id)return;const g=gesture;gesture=null;$('world').classList.remove('dragging');if(!g.moved){const p=worldPoint(e);if(p.y<55){say('아래 물건을 눌러 보거나 배경을 좌우로 밀어봐.');return;}busy=true;await moveTo(p,0);busy=false;}});viewport.addEventListener('pointercancel',()=>{gesture=null;$('world').classList.remove('dragging');});
const actorEl=$('actor');actorEl.addEventListener('pointerdown',e=>{if(busy||e.button!==0)return;e.stopPropagation();actorGesture={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};actorEl.setPointerCapture(e.pointerId);actorEl.style.transition='none';});
actorEl.addEventListener('pointermove',e=>{if(!actorGesture||e.pointerId!==actorGesture.id)return;if(Math.hypot(e.clientX-actorGesture.x,e.clientY-actorGesture.y)>7)actorGesture.moved=true;if(!actorGesture.moved)return;const p=worldPoint(e);actor.x=Math.max(8,Math.min(92,p.x));actor.y=Math.max(45,Math.min(87,p.y));pose(e.clientX<actorGesture.x?2:3);actorPosition();});
actorEl.addEventListener('pointerup',e=>{if(!actorGesture||e.pointerId!==actorGesture.id)return;e.stopPropagation();const g=actorGesture;actorGesture=null;actorEl.style.transition='';if(actorEl.hasPointerCapture(e.pointerId))actorEl.releasePointerCapture(e.pointerId);if(!g.moved){pose(actor.pose===1?7:1);say('단추: “한 가지 물건도 다른 쓰임이 있을 수 있어.”');return;}if(level().room===0&&actor.x<36&&actor.y<80){actor.x=24;actor.y=64;pose(4);say('단추가 이불을 덮고 잠깐 쉬어. 다시 끌면 일어날 수 있어.');}else if((level().room===0&&actor.x>68&&actor.y<75)||(level().room===1&&actor.x<40&&actor.y<77)){pose(5);say('단추가 두 손으로 빛을 가리고 하늘을 봐. “온실에서도 이 별이 보일까?”');}else pose(0);actorPosition();});
actorEl.addEventListener('pointercancel',()=>{actorGesture=null;actorEl.style.transition='';pose(0);actorPosition();});actorEl.addEventListener('keydown',e=>{if(busy)return;const dirs={ArrowLeft:[-7,0],ArrowRight:[7,0],ArrowUp:[0,-5],ArrowDown:[0,5]};if(dirs[e.key]){e.preventDefault();actor.x=Math.max(8,Math.min(92,actor.x+dirs[e.key][0]));actor.y=Math.max(45,Math.min(87,actor.y+dirs[e.key][1]));pose(dirs[e.key][0]<0?2:3);actorPosition();focusAt(actor.x);}else if(e.key==='Enter'||e.key===' '){e.preventDefault();pose(1);say('단추가 다음에 사용할 물건을 생각하고 있어.');}});
// Item drag/drop uses the same validated engine actions as tapping.
let itemDrag=null,suppressItemClick=false;
document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-item]');if(!b||busy||e.button!==0)return;itemDrag={id:e.pointerId,item:b.dataset.item,x:e.clientX,y:e.clientY,moved:false,ghost:null};});
document.addEventListener('pointermove',e=>{if(!itemDrag||e.pointerId!==itemDrag.id)return;if(Math.hypot(e.clientX-itemDrag.x,e.clientY-itemDrag.y)>10)itemDrag.moved=true;if(itemDrag.moved){e.preventDefault();if(!itemDrag.ghost){const el=document.createElement('div');el.className='flying-item';el.innerHTML=art(itemDrag.item);document.body.append(el);itemDrag.ghost=el;}itemDrag.ghost.style.left=e.clientX-40+'px';itemDrag.ghost.style.top=e.clientY-40+'px';}}, {passive:false});
document.addEventListener('pointerup',e=>{if(!itemDrag||e.pointerId!==itemDrag.id)return;const d=itemDrag;itemDrag=null;d.ghost?.remove();if(!d.moved)return;suppressItemClick=true;setTimeout(()=>suppressItemClick=false,300);const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-object],[data-item]');if(target?.dataset.object)perform({type:'use',item:d.item,target:target.dataset.object});else if(target?.dataset.item&&target.dataset.item!==d.item)perform({type:'combine',items:[d.item,target.dataset.item]});else say('물건 위에 놓아 사용하거나 소지품 두 개를 골라 조합해 봐.');});document.addEventListener('pointercancel',()=>{itemDrag?.ghost?.remove();itemDrag=null;});
window.addEventListener('resize',()=>{layout();renderObjects();actorPosition();});enterStage();if(state.flags.done)showSuccess('이 장면의 목표를 완료했어. 다음 이야기를 이어가자.');if(!raw)$('welcome').showModal();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
